using System;
using System.IO;
using System.Linq;
using System.Collections.Generic;
using Creezio.Switcher;
internal static class PortalComposerTests
{
    private static void Assert(bool value,string reason){if(!value)throw new Exception(reason);}
    private static void Reject(Action action){try{action();}catch(WebhookException e){Assert(e.StatusCode==409,"Unexpected composer rejection");return;}throw new Exception("Composer should reject invalid selection");}
    private static object Normal(object value){return Json.Read<object>(Json.Write(value));}
    private static PortalInstanceGrant Grant(){return new PortalInstanceGrant{InstanceId=new string('a',32),AccountKey="fictional-composer-account",Access="desktop",Model="gpt-6.1-sol",ReasoningEffort="ultra"};}
    private static PortalComposerInventory Catalog(){return new PortalComposerInventory{Models=new[]{Normal(new{id="gpt-6.1-sol",reasoningEfforts=new[]{"low","high","ultra"},inputModalities=new[]{"text","image"}}),Normal(new{id="gpt-6-astra",reasoningEfforts=new[]{"high","max"},inputModalities=new[]{"text","image"}})},SupportsPlanMode=true,Plugins=new[]{new PortalPluginReference{Id="fixture-plugin@local",Name="Fixture plugin",Enabled=true,InvokeSupported=true},new PortalPluginReference{Id="connector_fixture",Name="Fixture app",Enabled=true,InvokeSupported=true},new PortalPluginReference{Id="disabled-fixture@local",Name="Disabled",Enabled=false,InvokeSupported=false}}};}
    internal static void RunAll(Action<string,Action> check,string root)
    {
        check("composer durable followup uses the pinned native cwd and rejects a foreign root receipt",()=>{
            string original=Path.GetFullPath(root),native=Path.Combine(original,"native-chat"),home=Path.Combine(original,"fictional-home"),id=new string('a',32),thread="01a14ad6-eaff-7671-ae85-99ab61d47587";var route=new WebhookRoute{AccountKey="fixture-account",Home=home,Workspace=original};var created=new WebhookJob{Id=id,RouteId="fixture-route",PortalInstanceId="fixture-instance",ThreadId=thread,RouteSnapshot=route};var creation=new RelayMessage{Id=id,WebhookJobId=id,OperatorOrigin=true,NewConversation=true,TargetAccountKey=route.AccountKey,TargetHome=home,TargetThreadId=thread,NativeComposerWorkspace=native};Assert(PortalNativeComposer.ExpectedWorkspace(creation,created)==native,"New native cwd was not pinned");var followup=new WebhookJob{PortalChatId=id,RouteId=created.RouteId,PortalInstanceId=created.PortalInstanceId,RouteSnapshot=route};var message=new RelayMessage{TargetAccountKey=route.AccountKey,TargetHome=home,TargetThreadId=thread};Assert(PortalNativeComposer.ExpectedWorkspace(message,followup,created,creation)==native&&route.Workspace==original,"Durable followup changed the mandate or reused its cwd");foreach(string field in new[]{"account","home","thread","pin","operator"}){var tampered=Json.Read<RelayMessage>(Json.Write(creation));if(field=="account")tampered.TargetAccountKey="foreign";else if(field=="home")tampered.TargetHome=Path.Combine(home,"foreign");else if(field=="thread")tampered.TargetThreadId=Guid.NewGuid().ToString();else if(field=="pin")tampered.NativeComposerWorkspace=null;else tampered.OperatorOrigin=false;bool rejected=false;try{PortalNativeComposer.ExpectedWorkspace(message,followup,created,tampered);}catch(InvalidOperationException){rejected=true;}Assert(rejected,"Foreign durable root receipt accepted: "+field);}
        });
        check("composer explicit creation preflight preserves account PID binding and leaves global defaults intact",()=>{
            var target=new RelayChannel{Provider="codex",Id="fictional-profile",InstanceId=new string('c',32),AccountKey="fictional-account",Home=Path.GetFullPath(root),Workspace=Path.GetFullPath(root),PipePath="fictional-pinned-pipe",ServerPid=123,ServerStartTicks=456,RequireFullAccess=true};var message=new RelayMessage{OperatorOrigin=true,WebhookJobId=new string('a',32),ComposerOptions=new PortalMessageOptions{PermissionProfile="full-access"},ResolvedComposer=new PortalResolvedComposer{PermissionProfile="full-access"},NewConversation=true,DispatchPhase="preflight"};var prepared=PortalNativeComposer.PreflightChannel(target,message);Assert(target.RequireFullAccess&&!prepared.RequireFullAccess&&prepared.ServerPid==target.ServerPid&&prepared.ServerStartTicks==target.ServerStartTicks&&prepared.PipePath==target.PipePath&&AgentProviders.Binding(prepared)==AgentProviders.Binding(target),"No-tools preflight changed routing or global defaults");message.TargetThreadId=Guid.NewGuid().ToString();bool rejected=false;try{PortalNativeComposer.PreflightChannel(target,message);}catch(InvalidOperationException){rejected=true;}Assert(rejected,"Existing chat could bypass legacy guard without native verification");
        });
        check("composer refuses a moved or missing native workspace",()=>{
            PortalNativeComposer.RequireWorkspace(Path.GetFullPath(root),Path.GetFullPath(root));foreach(string value in new[]{(string)null,Path.Combine(Path.GetFullPath(root),"moved")}){bool rejected=false;try{PortalNativeComposer.RequireWorkspace(Path.GetFullPath(root),value);}catch(InvalidOperationException){rejected=true;}Assert(rejected,"Moved native chat accepted");}
        });
        check("composer accepts exact account model id and its advertised effort",()=>{
            var resolved=PortalComposer.ResolveSelections(Grant(),new PortalMessageOptions{Model="gpt-6.1-sol",ReasoningEffort="ultra"},Catalog());Assert(resolved.Model=="gpt-6.1-sol"&&resolved.ReasoningEffort=="ultra","Exact model changed");
        });
        check("composer rejects unknown model or effort unsupported by selected model",()=>{
            Reject(()=>PortalComposer.ResolveSelections(Grant(),new PortalMessageOptions{Model="unknown-model"},Catalog()));Reject(()=>PortalComposer.ResolveSelections(Grant(),new PortalMessageOptions{Model="gpt-6-astra",ReasoningEffort="ultra"},Catalog()));
        });
        check("composer never invents Plan mode when native catalog does not advertise it",()=>{
            var catalog=Catalog();catalog.SupportsPlanMode=false;Reject(()=>PortalComposer.ResolveSelections(Grant(),new PortalMessageOptions{CollaborationMode="plan"},catalog));
        });
        check("composer native plan packet preserves settings and has no permission overrides",()=>{
            var resolved=PortalComposer.ResolveSelections(Grant(),new PortalMessageOptions{CollaborationMode="plan",Model="gpt-6.1-sol",ReasoningEffort="ultra"},Catalog());var packet=Normal(PortalNativeComposer.Packet("01a14ad6-eaff-7671-ae85-99ab61d47587","Fictional turn",new string('b',32),resolved,"gpt-6.1-sol","ultra"));var request=Json.Get(Json.Get(packet,"turnStart"),"request");var mode=Json.Get(request,"collaborationMode");Assert(Json.Str(Json.Get(mode,"mode"))=="plan"&&Json.Str(Json.Get(Json.Get(mode,"settings"),"model"))=="gpt-6.1-sol","Plan mode was reduced to instructions");string json=Json.Write(packet);foreach(string forbidden in new[]{"approvalPolicy","permissions","sandboxPolicy","runtimeWorkspaceRoots","developer_instructions\":\""})Assert(!json.Contains(forbidden),"Native packet changed security setting "+forbidden);
        });
        check("composer plugin selection requires enabled account-specific catalog entries",()=>{
            Reject(()=>PortalComposer.ResolveSelections(Grant(),new PortalMessageOptions{Plugins=new List<string>{"other-account-plugin@local"}},Catalog()));Reject(()=>PortalComposer.ResolveSelections(Grant(),new PortalMessageOptions{Plugins=new List<string>{"disabled-fixture@local"}},Catalog()));var resolved=PortalComposer.ResolveSelections(Grant(),new PortalMessageOptions{Plugins=new List<string>{"fixture-plugin@local","connector_fixture"}},Catalog());string text=Json.Write(resolved);Assert(text.Contains("plugin://fixture-plugin@local")&&text.Contains("app://connector_fixture")&&resolved.InputItems.Length==2,"Selected plugin references were ignored");
        });
        check("composer malformed plugin identifier cannot inject extra markdown routing",()=>{
            var catalog=Catalog();catalog.Plugins=new[]{new PortalPluginReference{Id="x](https://attacker.example)",Name="Fake",Enabled=true,InvokeSupported=true}};Reject(()=>PortalComposer.ResolveSelections(Grant(),new PortalMessageOptions{Plugins=new List<string>{catalog.Plugins[0].Id}},catalog));
        });
        check("composer skill opaque id resolves to exact current SKILL file without exporting path",()=>{
            string folder=Path.Combine(Path.GetFullPath(root),"portal-composer-tests","valid-skill");Directory.CreateDirectory(folder);string path=Path.Combine(folder,"SKILL.md");File.WriteAllText(path,"Fictional skill only. Do not delegate.");var catalog=Catalog();catalog.Skills=new[]{new PortalSkillReference{Id=new string('c',64),Name="fixture-skill",Path=path,Enabled=true}};var resolved=PortalComposer.ResolveSelections(Grant(),new PortalMessageOptions{Skills=new List<string>{new string('c',64)}},catalog);Assert(Json.Write(resolved.InputItems).Contains("fixture-skill")&&Json.Write(resolved.InputItems).Contains("skill")&&!Json.Write(resolved.PublicMetadata).Contains("SKILL.md"),"Skill path leaked or native skill ignored");Reject(()=>PortalComposer.ResolveSelections(Grant(),new PortalMessageOptions{Skills=new List<string>{new string('d',64)}},catalog));catalog.Skills[0].Enabled=false;Reject(()=>PortalComposer.ResolveSelections(Grant(),new PortalMessageOptions{Skills=new List<string>{new string('c',64)}},catalog));
        });
        check("composer native packet carries images and mentions as structured input items",()=>{
            var resolved=new PortalResolvedComposer{InputItems=new[]{Normal(new{type="localImage",path="C:\\fictional\\image.png"}),Normal(new{type="mention",name="Fixture file",path="C:\\fictional\\file.txt"})}};var packet=Normal(PortalNativeComposer.Packet("01a14ad6-eaff-7671-ae85-99ab61d47587","Read fixture",new string('b',32),resolved,"gpt-6.1-sol","ultra"));var input=RelayEngine.Rows(Json.Get(Json.Get(Json.Get(packet,"turnStart"),"request"),"input")).ToArray();Assert(input.Length==3&&Json.Str(Json.Get(input[1],"type"))=="localImage"&&Json.Str(Json.Get(input[2],"type"))=="mention","Input items became plain text");
        });
        check("composer desktop gateway never receives unknown enrichment arguments",()=>{
            var message=new RelayMessage{WebhookJobId=new string('a',32),OperatorOrigin=true,RequestedModel="gpt-6.1-sol",RequestedReasoningEffort="ultra",TargetProvider="codex",ResolvedComposer=new PortalResolvedComposer{InputItems=new object[0]}};var args=new Dictionary<string,object>();WebhookDispatch.ApplyExecution(message,args);Assert(args.Count==2&&args.ContainsKey("model")&&args.ContainsKey("thinking"),"Unsupported gateway fields silently passed");message.TargetProvider="codex-headless";WebhookDispatch.ApplyExecution(message,args);Assert(args.ContainsKey("creezioComposer"),"Headless native composer missing");
        });
        check("composer rich native transport is selected only for rich desktop mandates",()=>{
            var message=new RelayMessage{ComposerOptions=new PortalMessageOptions{Attachments=new List<string>{new string('a',32)}}};Assert(PortalNativeComposer.RequiresNative(message,new RelayChannel{Provider="codex"}),"Desktop image ignored native adapter");Assert(!PortalNativeComposer.RequiresNative(message,new RelayChannel{Provider="codex-headless"}),"Headless used global desktop IPC");message.ComposerOptions=new PortalMessageOptions{Model="gpt-6.1-sol"};Assert(!PortalNativeComposer.RequiresNative(message,new RelayChannel{Provider="codex"}),"Plain model selection unnecessarily changed transport");
        });
        check("composer public model catalog preserves exact identifiers and effort choices",()=>{
            var model=PortalMcpCapabilities.PublicModel(Normal(new{id="catalog-entry",model="gpt-6.1-sol",displayName="GPT-6.1 Sol",description="Fixture",isDefault=true,defaultReasoningEffort="high",supportedReasoningEfforts=new[]{new{reasoningEffort="high"},new{reasoningEffort="ultra"}},inputModalities=new[]{"text","image"}}));Assert(Json.Str(Json.Get(model,"id"))=="gpt-6.1-sol"&&RelayEngine.Rows(Json.Get(model,"reasoningEfforts")).Count()==2,"Catalog id used instead of native model identifier");
        });
    }
}
